import{_ as e,o as s,c as a,a0 as i}from"./chunks/framework.BJ26GviO.js";const k=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md"}'),n={name:"guide/getting-started.md"};function r(h,t,o,d,l,p){return s(),a("div",null,[...t[0]||(t[0]=[i(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git:github.com/jawwadzafar/pi-webfind</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or, after the npm publish:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm:pi-webfind</span></span></code></pre></div><p>Pi loads the TypeScript extension directly — no build step, no config.</p><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><p>Seven tools and one command, all free:</p><table tabindex="0"><thead><tr><th>Tool</th><th>Best for</th></tr></thead><tbody><tr><td><code>web_search</code></td><td>news, articles, broad queries — set <code>deep: true</code> for excerpts</td></tr><tr><td><code>fetch_page</code></td><td>read a URL — pass <code>query</code> for relevant passages</td></tr><tr><td><code>search_stackoverflow</code></td><td>error messages, debugging</td></tr><tr><td><code>search_wikipedia</code></td><td>definitions, concepts, history</td></tr><tr><td><code>search_npm</code></td><td>JS/TS packages with quality scores</td></tr><tr><td><code>search_github</code></td><td>repos, stars, languages</td></tr><tr><td><code>search_hn</code></td><td>tech community opinion, launches</td></tr></tbody></table><p>Plus the <strong><code>/research &lt;topic&gt;</code></strong> command: parallel search across web, HN, GitHub and Wikipedia, fetches the top pages, then briefs you with &quot;documents worth reading + recurring conclusions&quot;.</p><h2 id="two-habits-that-get-better-answers" tabindex="-1">Two habits that get better answers <a class="header-anchor" href="#two-habits-that-get-better-answers" aria-label="Permalink to &quot;Two habits that get better answers&quot;">​</a></h2><p><strong>Search deep, not wide.</strong> For factual questions pass <code>deep: true</code> — the top results get read and each row carries a query-relevant excerpt. Often the answer is on screen without a single fetch.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;query&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;why does rust have lower latency than go&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;max_results&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;deep&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p><strong>Fetch with intent.</strong> Long pages return the passages that match your query, not the first 8000 characters:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://en.wikipedia.org/wiki/DuckDuckGo&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;query&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;how does duckduckgo make money&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><h2 id="caches" tabindex="-1">Caches <a class="header-anchor" href="#caches" aria-label="Permalink to &quot;Caches&quot;">​</a></h2><p>Search results (10 min) and fetched pages (1 h) are cached under <code>~/.pi/agent/cache/webfind/</code> and survive restarts. <code>refresh: true</code> / <code>no_cache: true</code> skip them.</p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><p>pi-webfind runs with full system access like any pi extension. It makes outbound HTTPS requests to search engines, public APIs and pages you fetch. It never reads your files, never executes fetched content, and blocks requests to localhost/private networks (SSRF guard). Engine traffic uses a politeness throttle; the only optional credential is <code>GITHUB_TOKEN</code> to lift GitHub&#39;s 10 req/min anonymous limit.</p>`,17)])])}const u=e(n,[["render",r]]);export{k as __pageData,u as default};
